  const sx = x+wx, sy = y+wy;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.07, 2.1],
    [340+Math.cos(t*0.45)*95, 150+Math.sin(t*0.6)*60, 0.09, 1.8],
